PREFIX edm: <http://www.europeana.eu/schemas/edm/>

SELECT ?DataProvider
WHERE { ?Aggregation edm:dataProvider ?DataProvider }

PREFIX edm: <http://www.europeana.eu/schemas/edm/>

SELECT DISTINCT ?Dataset
WHERE {
 ?Aggregation edm:datasetName ?Dataset ;
 edm:country "Italy"
}

PREFIX ore: <http://www.openarchives.org/ore/terms/>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>

SELECT DISTINCT ?ProvidedCHO ?year
WHERE {
 ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
 edm:country "France" .
 ?Proxy ore:proxyFor ?ProvidedCHO ;
 edm:year ?year .
 FILTER (?year > "1700" && ?year < "1800")
}
ORDER BY asc(?year)
LIMIT 100

#Get information of Europeana item using federated query
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX edm: <http://www.europeana.eu/schemas/edm/>
PREFIX ore: <http://www.openarchives.org/ore/terms/>

SELECT * WHERE {
 BIND(<http://data.europeana.eu/proxy/provider/91622/raa_kmb_16000200042758> as ?p854) 
 SERVICE <http://sparql.europeana.eu/> {
 {
 ?p854 <http://purl.org/dc/terms/created> ?created .
 ?p854 <http://purl.org/dc/elements/1.1/identifier> ?identifier .
 ?p854 <http://purl.org/dc/elements/1.1/publisher> ?publisher .
 ?p854 <http://purl.org/dc/elements/1.1/rights> ?rights .
 ?p854 <http://purl.org/dc/elements/1.1/title> ?title .
 ?p854 <http://purl.org/dc/elements/1.1/description> ?description .
 }
 }
}

SELECT ?EuropeanaType (count(*) as ?count) 
WHERE {
 ?Aggregation edm:isShownBy|edm:hasView ?WebResource .
 ?Proxy ore:proxyIn ?Aggregation ;
 edm:type ?EuropeanaType . 
}
GROUP BY ?EuropeanaType

SELECT ?Rights (count(*) as ?count) 
WHERE {
 ?Aggregation edm:rights ?Rights ;
 edm:isShownBy|edm:hasView ?WebResource
}
GROUP BY ?Rights
ORDER BY DESC (?count)

PREFIX edm: <http://www.europeana.eu/schemas/edm/>
PREFIX ore: <http://www.openarchives.org/ore/terms/>
SELECT ?Dataset
       (COUNT(DISTINCT ?WebResource) AS ?videoResources)
       (COUNT(DISTINCT ?ProvidedCHO) AS ?objects)
WHERE {
  { SELECT ?Aggregation WHERE { ?Proxy ore:proxyIn ?Aggregation ; edm:type "VIDEO" } }
  ?Aggregation edm:rights ?Rights ;
               edm:aggregatedCHO ?ProvidedCHO .
  { ?Aggregation edm:isShownBy ?WebResource }
  UNION
  { ?Aggregation edm:hasView ?WebResource }
  ?EuropeanaAggregation edm:aggregatedCHO ?ProvidedCHO ;
                        edm:datasetName ?Dataset .
  FILTER (REGEX(STR(?Rights),
          "^https?://creativecommons\\.org/(publicdomain/(zero|mark)|licen[sc]es/(by|by-sa))/"))
}
GROUP BY ?Dataset
ORDER BY DESC(?videoResources)

SELECT DISTINCT ?Agent
WHERE {
 ?Agent rdf:type edm:Agent .
 FILTER strstarts(str(?Agent), "http://viaf.org/viaf/")
}
LIMIT 10

SELECT DISTINCT ?ProvidedCHO
WHERE {
 ?Place rdf:type edm:Agent .
 ?Proxy ?property ?Agent ;
 ore:proxyFor ?ProvidedCHO
}
LIMIT 10

SELECT DISTINCT ?ProvidedCHO
WHERE {
 ?Proxy ?property ?Agent ;
 ore:proxyFor ?ProvidedCHO .
 ?Agent rdf:type edm:Agent .
 FILTER strstarts(str(?Agent), "http://viaf.org/viaf/")
}
LIMIT 10

SELECT DISTINCT ?Place
WHERE {
 ?Place rdf:type edm:Place .
 FILTER strstarts(str(?Place), "http://sws.geonames.org/")
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
 ?Place rdf:type edm:Place .
 ?Proxy dcterms:spatial|dc:coverage ?Place ;
 ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?Concept
WHERE {
 ?Concept rdf:type skos:Concept .
 FILTER strstarts(str(?Concept), "http://vocab.getty.edu/aat/") .
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
 ?Proxy dc:type|dc:subject ?Concept ;
 ore:proxyFor ?ProvidedCHO
}

SELECT DISTINCT ?ProvidedCHO
WHERE {
 ?Time rdf:type edm:TimeSpan .
 ?Proxy ?property ?Time ;
 ore:proxyFor ?ProvidedCHO
}

SELECT ?Provider (count(*) as ?count)
WHERE {
 ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
 edm:provider ?Provider .
}
GROUP BY ?Provider 
ORDER BY DESC(?count)

SELECT ?Provider ?DataProvider (count(*) as ?count)
WHERE {
 ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
 edm:provider ?Provider ;
 edm:dataProvider ?DataProvider
}
GROUP BY ?Provider ?DataProvider 
ORDER BY ?Provider ?DataProvider

SELECT ?Country (count(*) as ?count)
WHERE {
 ?Aggregation edm:aggregatedCHO ?ProvidedCHO ;
 edm:country ?Country .
}
GROUP BY ?Country
ORDER BY DESC(?count)

SELECT ?Country ?EuropeanaType (COUNT(DISTINCT ?ProvidedCHO) AS ?count)
WHERE {
 ?AggregationEuropeana edm:country ?Country ;
 edm:aggregatedCHO ?ProvidedCHO .
 ?Proxy ore:proxyIn ?AggregationEuropeana ;
 edm:type ?EuropeanaType .
}
GROUP BY ?Country ?EuropeanaType 
ORDER BY ?Country ?EuropeanaType

SELECT ?Lang (count(*) as ?count) 
WHERE {
 ?Aggregation edm:language ?Lang ;
 edm:aggregatedCHO ?ProvidedCHO .
}
GROUP BY ?Lang
ORDER BY DESC(?count)

SELECT DISTINCT ?Dataset
WHERE {
 ?Aggregation edm:datasetName ?Dataset .
 ?Proxy ore:proxyIn ?Aggregation ;
 edm:type "VIDEO"
}

SELECT DISTINCT ?Dataset
WHERE {
 ?Aggregation edm:datasetName ?Dataset ;
 edm:country "netherlands" .
 ?Proxy ore:proxyIn ?Aggregation ;
 edm:type "VIDEO"
}

