(GROUP_CONCAT( DISTINCT ?time_evidence_text ; separator=", " ) as ?time_evidence_texts )
WHERE{
 {
 # Search participant
 ?meetup mtp:hasParticipant/mtp:hasEntity/rdfs:label ?lit .
